ericBaseDc":"19 + spell level","wizardSpellsPerDayLevels0To17":"4/9/8/8/8/8/7/7/7/7/3/3/3/3/2/2/2/2","wizardBaseDc":"27 + spell level"},"possessions":{"dagger":"+5 ghost touch keen unholy dagger; a mortal struck can be controlled as if by Control Creatures (undead), and controlled mortals count against the same creature limit."},"automaticActions":{"skills":["Alchemy","Knowledge (arcana)","Knowledge (geography)","Knowledge (history)","Knowledge (nature)","Knowledge (religion)","Knowledge (the planes)","Knowledge (undead)","Profession (herbalist)","Spellcraft"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":5,"armorClass":41,"attacks":"dagger +59/+54/+49/+44, 1d6+12/18-20","spellTouch":{"melee":53,"ranged":55},"damageReduction":"40/+4","fireResistance":25,"spellResistance":37,"divineAura":{"radiusFeet":500,"dc":25},"saves":{"fort":44,"ref":46,"will":48},"salientDivineAbilities":["Alter Size","Alter Form","Dark Celerity","Divine Spellcasting","Extra Domain (Knowledge)","Increased Spell Resistance"],"spellLikeCasterLevel":15,"spellLikeSaveDc":"25 + spell level"},"revision3_5":{"alignmentSubtypes":["evil"],"damageReduction":"25/epic","fireResistance":16,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules where relevant.","defunctSkills":["Alchemy -> Craft (alchemy)","Knowledge (undead) ranks reassigned","Scry ranks reassigned","Wilderness Lore -> Survival/appropriate revised skills"]}}'),

('dd-statblock-hephaestus','Hephaestus Divine Stat Block','119-120',
 'Hephaestus is the divine-rank-15 intermediate Olympian deity of smithing and crafts.',
 '{"deitySlug":"hephaestus","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["Workman of the Immortals","God of the Forge"],"symbol":"Hammer and anvil","homePlane":"Olympus","alignment":"NG","classes":[{"class":"Fighter","level":15},{"class":"Cleric","level":12},{"class":"Expert","level":8}],"creature":{"type":"Outsider","subtypes":["Good"],"size":"Large","hitDice":"20d8+180 outsider + 15d10+135 fighter + 12d8+108 cleric + 8d6+72 expert","hitPoints":879,"initiative":12,"speed":{"land":60},"armorClass":{"total":69,"size":-1,"dexterity":8,"divine":15,"natural":28,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"warhammer":"+80/+75/+70/+65 melee, Huge +5 flaming burst warhammer","damage":"2d8+37/19-20/x3","spellTouch":{"melee":74,"ranged":62}},"saves":{"fort":56,"ref":55,"will":56,"intermediateDeityChecksAlways20":true},"abilities":{"str":51,"dex":27,"con":28,"int":30,"wis":29,"cha":29},"specialAttacks":{"turnUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"50/+4","printedFireImmunity":true,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":34},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Annihilating Strike","Area Divine Shield","Avatar","Craft Artifact","Create Greater Object","Create Object","Divine Blast","Divine Creation","Divine Fire Mastery","Divine Shield","Energy Storm (fire)","Extra Domain (Community)","Extra Domain (Good)","Irresistible Blows (warhammer)","Master Crafter"],"domainPowers":{"creationSpellsCasterLevelBonus":1,"calmEmotionsUsesPerDay":15,"earthTurningUsesPerDay":15,"fireTurningUsesPerDay":15,"goodSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":25,"creationAndGoodCasterLevel":26,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/7/7/6/6/4","clericBaseDc":"19 + spell level"},"automaticActions":{"skills":["Craft (armorsmithing)","Craft (bowmaking)","Craft (metalworking)","Craft (weaponsmithing)","Knowledge (arcana)","Knowledge (architecture and engineering)","Knowledge (geography)","Knowledge (nature)","Knowledge (religion)","Knowledge (the planes)","Profession (miner)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"size":"Medium","alignmentSubtype":"Good","speed":{"land":40},"armorClass":53,"attacks":"Large +5 flaming burst returning warhammer +72/+67/+62/+57, 1d8+37/x3","spellTouch":{"melee":66,"ranged":54},"damageReduction":"42/+4","spellResistance":39,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":48,"ref":47,"will":48},"salientDivineAbilities":["Alter Form","Alter Size","Area Divine Shield","Create Object","Divine Fire Mastery","Divine Shield","Extra Domain (Community)","Extra Domain (Good)","Master Crafter"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"25/epic","rankBasedFireResistance":20,"printedFireImmunityPreserved":"The 3.0 main block prints fire immunity rather than resistance; do not silently replace the printed source field. Apply the official revision carefully when constructing a 3.5-effective block.","additionalOutsiderSkillPoints":true,"skillFocus":"Use revised +3 Skill Focus bonus.","defunctFeat":"Improved Sunder is obsolete in the update and should use the revised Improved Sunder treatment."}}'),

('dd-statblock-hera','Hera Divine Stat Block','120-122',
 'Hera is the divine-rank-16 greater Olympian deity of marriage, women, and intrigue.',
