,"protectiveWardUsesPerDay":16,"protectiveWardResistanceBonus":16},"spellLikeAbilities":{"casterLevel":26,"saveDc":"42 + spell level"},"spellcasting":{"wizardSpellsPerDay":"4/6/6/6/6/5/5/5/5/4","wizardBaseDc":"18 + spell level"},"senses":{"normalSenseRangeMiles":16,"hearingRangeMiles":32,"penetratingVisionFeet":160},"automaticActions":{"skills":"Charisma- or Intelligence-related skills in which she has ranks or that are usable untrained","freeActionDcMaximum":30,"maximumPerRound":20},"avatar":{"divineRank":8,"armorClass":65,"attacks":"heavy mace +65/+60/+55/+50, 1d8+23","spellTouch":{"melee":59,"ranged":58},"damageReduction":"43/+4","fireResistance":28,"fastHealing":false,"spellResistance":40,"divineAura":{"radiusFeet":800,"dc":34},"saves":{"fort":49,"ref":51,"will":50},"salientDivineAbilities":["Alter Form","Alter Size","Arcane Mastery","Automatic Metamagic (extend wizard spells)","Divine Blast","Divine Shield","Extra Domain (Protection)","Extra Sense Enhancement (hearing)","Extra Sense Enhancement (sight)","Shapechange"],"spellLikeCasterLevel":18,"spellLikeSaveDc":"34 + spell level"},"revision3_5":{"alignmentSubtypes":[],"damageReduction":"30/epic","fireResistance":21,"additionalOutsiderSkillPoints":true,"rogue":"Additional +2 against traps under revised rogue rules.","skillFocus":"Use revised +3 Skill Focus bonus.","wizardSpecialization":"Apply revised school-specialization rules where relevant.","defunctSkills":["Alchemy -> Craft (alchemy)","Innuendo ranks reassigned","Pick Pocket -> Sleight of Hand","Scry ranks reassigned"]}}')
